diff --git a/src/lib/OpenEXR/ImfIDManifest.cpp b/src/lib/OpenEXR/ImfIDManifest.cpp
index 4a41f27..27e6957 100644
--- a/src/lib/OpenEXR/ImfIDManifest.cpp
+++ b/src/lib/OpenEXR/ImfIDManifest.cpp
@@ -338,6 +338,16 @@ writePascalString (char*& outPtr, const string& str)
     Xdr::write<CharPtrIO> ((char*&) outPtr, (const char*) str.c_str (), length);
 }

+//
+// checks that at least n bytes are available, starting at data, before
+// endOfData is reached
+//
+bool
+haveBytes (const char* data, const char* endOfData, size_t n)
+{
+    return data + n - 1 <= endOfData;
+}
+
 } // namespace

 IDManifest::IDManifest (const char* data, const char* endOfData)
@@ -478,7 +488,8 @@ IDManifest::init (const char* data, const char* endOfData)

     _manifest.clear ();

-    if (manifestEntries <0)
+    if (manifestEntries < 0 ||
+        ! haveBytes (data, endOfData, (size_t) manifestEntries))
     {
         throw IEX_NAMESPACE::InputExc ("bad number of ChannelGroupsManifests in IDManifest");
     }

